INSERT OR IGNORE INTO core_feature_flags (key, description, default_enabled, environment, enabled, created_by, source_type)
VALUES ('ff.eng.p0404', 'Part 04.04 Protocol and Control Engine: control points, exceptions and reason codes', 0, NULL, 0, 'migration', 'reference_seed');
