SELECT 'ff.eng.p0404', 'Part 04.04 Protocol and Control Engine: control points, exceptions and reason codes', 0, env.name, 1, 'migration', 'reference_seed'
FROM (SELECT 'development' AS name UNION ALL SELECT 'test') AS env;
